@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&family=Playfair+Display:wght@400;500;600;700&display=swap');

:root {
  --green: #00824A;
  --green-dark: #006B3D;
  --green-light: #E8F5EE;
  --forest: #32462F;
  --cream: #F3CEA1;
  --cream-light: #FDF6EC;
  --cream-dark: #E8B97A;
  --brown: #5C4033;
  --brown-light: #8B6F5E;
  --white: #FFFFFF;
  --off-white: #FAFAF8;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --gray-800: #1F2937;
  --gray-900: #111827;
  --font-body: 'DM Sans', system-ui, -apple-system, sans-serif;
  --font-heading: 'Playfair Display', Georgia, serif;
  --radius-sm: 0.375rem;
  --radius-md: 0.625rem;
  --radius-lg: 1rem;
  --radius-xl: 1.5rem;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.08), 0 8px 10px -6px rgba(0,0,0,0.04);
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
}

*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  color: var(--gray-800);
  background: var(--white);
  line-height: 1.6;
  font-size: 16px;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  font-family: inherit;
  border: none;
  background: none;
}

h1, h2, h3, h4 {
  font-family: var(--font-heading);
  color: var(--forest);
  line-height: 1.2;
}

.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* ── HEADER ── */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--transition-base);
}

.site-header.scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  font-family: var(--font-heading);
  font-size: 1.375rem;
  font-weight: 700;
  color: var(--green);
}

.logo-icon {
  width: 40px;
  height: 40px;
  background: var(--green);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
}

.logo-icon svg {
  width: 22px;
  height: 22px;
  color: var(--white);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
  list-style: none;
}

.nav-links a {
  font-weight: 500;
  font-size: 0.9375rem;
  color: var(--gray-700);
  transition: color var(--transition-fast);
  position: relative;
  padding: 0.25rem 0;
}

.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--green);
  transition: width var(--transition-base);
  border-radius: 1px;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--green);
}

.nav-links a:hover::after,
.nav-links a.active::after {
  width: 100%;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.625rem 1.25rem;
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.btn-primary {
  background: var(--green);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--green-dark);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background: transparent;
  color: var(--gray-700);
  border: 1.5px solid var(--gray-300);
}

.btn-secondary:hover {
  border-color: var(--green);
  color: var(--green);
}

.btn-outline-green {
  background: transparent;
  color: var(--green);
  border: 1.5px solid var(--green);
}

.btn-outline-green:hover {
  background: var(--green);
  color: var(--white);
}

.btn-lg {
  padding: 0.875rem 2rem;
  font-size: 1rem;
}

.btn-sm {
  padding: 0.375rem 0.875rem;
  font-size: 0.8125rem;
}

.mobile-menu-btn {
  display: none;
  width: 44px;
  height: 44px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-md);
}

.mobile-menu-btn:hover {
  background: var(--gray-100);
}

.hamburger {
  width: 22px;
  height: 16px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.hamburger span {
  display: block;
  width: 100%;
  height: 2px;
  background: var(--gray-700);
  border-radius: 1px;
  transition: all var(--transition-fast);
}

.mobile-nav {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--white);
  z-index: 99;
  padding: 1.5rem;
  flex-direction: column;
  gap: 0.5rem;
  overflow-y: auto;
}

.mobile-nav.open {
  display: flex;
}

.mobile-nav a {
  display: block;
  padding: 1rem;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--gray-700);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.mobile-nav a:hover,
.mobile-nav a.active {
  background: var(--green-light);
  color: var(--green);
}

.mobile-nav .mobile-actions {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-top: 1rem;
  padding-top: 1rem;
  border-top: 1px solid var(--gray-200);
}

/* ── FOOTER ── */
.site-footer {
  background: var(--forest);
  color: var(--white);
  padding: 4rem 0 2rem;
  margin-top: 5rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 2rem;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.footer-col h4 {
  color: var(--cream);
  font-family: var(--font-body);
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 1.25rem;
  cursor: default;
}

.footer-col .accordion-icon {
  display: none;
}

.footer-col ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

.footer-col a {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.75);
  transition: color var(--transition-fast);
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  max-width: 1280px;
  margin: 0 auto;
  padding: 2rem 1.5rem 0;
  margin-top: 3rem;
  border-top: 1px solid rgba(255,255,255,0.15);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
}

.footer-social {
  display: flex;
  gap: 1rem;
}

.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-full);
  background: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
}

.footer-social a:hover {
  background: var(--green);
}

.footer-social svg {
  width: 18px;
  height: 18px;
  color: var(--white);
}

.footer-legal {
  font-size: 0.75rem;
  color: rgba(255,255,255,0.5);
}

.footer-legal a {
  color: rgba(255,255,255,0.65);
}

.footer-legal a:hover {
  color: var(--white);
}

/* ── COOKIE BANNER ── */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 200;
  background: var(--white);
  box-shadow: 0 -4px 20px rgba(0,0,0,0.12);
  padding: 1.25rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.5rem;
  flex-wrap: wrap;
  transition: transform var(--transition-slow);
}

.cookie-banner.hidden {
  transform: translateY(100%);
  pointer-events: none;
}

.cookie-banner p {
  font-size: 0.875rem;
  color: var(--gray-600);
  max-width: 600px;
}

.cookie-banner strong {
  color: var(--gray-800);
  display: block;
  margin-bottom: 0.25rem;
}

.cookie-actions {
  display: flex;
  gap: 0.75rem;
  flex-shrink: 0;
}

/* ── SECTION UTILITIES ── */
.section {
  padding: 5rem 0;
}

.section-sm {
  padding: 3rem 0;
}

.section-alt {
  background: var(--off-white);
}

.section-green {
  background: var(--green-light);
}

.text-center {
  text-align: center;
}

.text-green {
  color: var(--green);
}

.text-muted {
  color: var(--gray-500);
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.25rem 0.75rem;
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.badge-green {
  background: var(--green-light);
  color: var(--green);
}

.badge-cream {
  background: var(--cream-light);
  color: var(--brown);
}

/* ── CARDS ── */
.card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
  border: 1px solid var(--gray-100);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.card-img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  background: var(--gray-100);
}

.card-body {
  padding: 1.25rem;
}

.card-title {
  font-size: 1.125rem;
  font-weight: 600;
  margin-bottom: 0.375rem;
}

.card-text {
  font-size: 0.875rem;
  color: var(--gray-500);
}

/* ── SPLIT SECTION (image + text) ── */
.split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  min-height: 420px;
  border-radius: var(--radius-xl);
  overflow: hidden;
  background: var(--off-white);
}

.split-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  background: var(--gray-200);
  min-height: 300px;
}

.split-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 3rem;
}

.split-content h2 {
  font-size: 2rem;
  margin-bottom: 1rem;
}

.split-content p {
  font-size: 1rem;
  color: var(--gray-600);
  margin-bottom: 1.5rem;
  line-height: 1.7;
}

.split.reverse .split-img {
  order: 2;
}

.split.reverse .split-content {
  order: 1;
}

/* ── CAROUSEL ── */
.carousel-wrapper {
  position: relative;
}

.carousel-track {
  display: flex;
  gap: 1.25rem;
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 0.5rem 0;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

.carousel-track > * {
  scroll-snap-align: start;
  flex-shrink: 0;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  background: var(--white);
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 5;
  transition: all var(--transition-fast);
  border: 1px solid var(--gray-200);
}

.carousel-btn:hover {
  background: var(--green);
  color: var(--white);
  border-color: var(--green);
}

.carousel-btn svg {
  width: 20px;
  height: 20px;
}

.carousel-btn.prev {
  left: -22px;
}

.carousel-btn.next {
  right: -22px;
}

/* ── TABS ── */
.tabs {
  display: flex;
  gap: 0.25rem;
  overflow-x: auto;
  scrollbar-width: none;
  padding: 0.25rem;
  background: var(--gray-100);
  border-radius: var(--radius-full);
  width: fit-content;
  max-width: 100%;
}

.tabs::-webkit-scrollbar {
  display: none;
}

.tab-btn {
  padding: 0.625rem 1.25rem;
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  color: var(--gray-500);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.tab-btn:hover {
  color: var(--gray-700);
}

.tab-btn.active {
  background: var(--white);
  color: var(--green);
  box-shadow: var(--shadow-sm);
}

.tab-panel {
  display: none;
  animation: fadeIn 300ms ease;
}

.tab-panel.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ── PLACEHOLDER IMAGES ── */
.img-placeholder {
  background: linear-gradient(135deg, var(--cream-light) 0%, var(--gray-100) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400);
  font-size: 0.75rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* ── RESPONSIVE ── */
@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }
  .split {
    grid-template-columns: 1fr;
    min-height: auto;
  }
  .split-content {
    padding: 2rem;
  }
  .split.reverse .split-img {
    order: 0;
  }
  .split.reverse .split-content {
    order: 0;
  }
}

@media (max-width: 768px) {
  .nav-links,
  .header-actions {
    display: none;
  }
  .mobile-menu-btn {
    display: flex;
  }
  .section {
    padding: 3rem 0;
  }
  .split-content h2 {
    font-size: 1.5rem;
  }
  .footer-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .footer-col {
    border-bottom: 1px solid rgba(255,255,255,0.1);
  }
  .footer-col h4 {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 0;
    margin-bottom: 0;
    cursor: pointer;
  }
  .footer-col .accordion-icon {
    display: block;
    transition: transform var(--transition-fast);
  }
  .footer-col.open .accordion-icon {
    transform: rotate(180deg);
  }
  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--transition-base), padding var(--transition-base);
    padding-bottom: 0;
  }
  .footer-col.open ul {
    max-height: 500px;
    padding-bottom: 1rem;
  }
  .carousel-btn.prev { left: 4px; }
  .carousel-btn.next { right: 4px; }
  .cookie-banner {
    flex-direction: column;
    text-align: center;
  }
  .tabs {
    width: 100%;
    justify-content: flex-start;
  }
}

