/* ── COOKIE BANNER ── */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 200;
  background: var(--white);
  box-shadow: 0 -4px 20px rgba(0,0,0,0.12);
  padding: 1.25rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.5rem;
  flex-wrap: wrap;
  transition: transform var(--transition-slow);
}

.cookie-banner.hidden {
  transform: translateY(100%);
  pointer-events: none;
}

.cookie-banner p {
  font-size: 0.875rem;
  color: var(--gray-600);
  max-width: 600px;
}

.cookie-banner strong {
  color: var(--gray-800);
  display: block;
  margin-bottom: 0.25rem;
}

.cookie-actions {
  display: flex;
  gap: 0.75rem;
  flex-shrink: 0;
}

/* ── SECTION UTILITIES ── */
.section {
  padding: 5rem 0;
}

.section-sm {
  padding: 3rem 0;
}

.section-alt {
  background: var(--off-white);
}

.section-green {
  background: var(--green-light);
}

.text-center {
  text-align: center;
}

.text-green {
  color: var(--green);
}

.text-muted {
  color: var(--gray-500);
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.25rem 0.75rem;
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.badge-green {
  background: var(--green-light);
  color: var(--green);
}

.badge-cream {
  background: var(--cream-light);
  color: var(--brown);
}

/* ── CARDS ── */
.card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
  border: 1px solid var(--gray-100);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.card-img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  background: var(--gray-100);
}

.card-body {
  padding: 1.25rem;
}

.card-title {
  font-size: 1.125rem;
  font-weight: 600;
  margin-bottom: 0.375rem;
}

.card-text {
  font-size: 0.875rem;
  color: var(--gray-500);
}

/* ── SPLIT SECTION (image + text) ── */
.split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  min-height: 420px;
  border-radius: var(--radius-xl);
  overflow: hidden;
  background: var(--off-white);
}

.split-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  background: var(--gray-200);
  min-height: 300px;
}

.split-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 3rem;
}

.split-content h2 {
  font-size: 2rem;
  margin-bottom: 1rem;
}

.split-content p {
  font-size: 1rem;
  color: var(--gray-600);
  margin-bottom: 1.5rem;
  line-height: 1.7;
}

.split.reverse .split-img {
  order: 2;
}

.split.reverse .split-content {
  order: 1;
}

/* ── CAROUSEL ── */
.carousel-wrapper {
  position: relative;
}

.carousel-track {
  display: flex;
  gap: 1.25rem;
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 0.5rem 0;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

.carousel-track > * {
  scroll-snap-align: start;
  flex-shrink: 0;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  background: var(--white);
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 5;
  transition: all var(--transition-fast);
  border: 1px solid var(--gray-200);
}

.carousel-btn:hover {
  background: var(--green);
  color: var(--white);
  border-color: var(--green);
}

.carousel-btn svg {
  width: 20px;
  height: 20px;
}

.carousel-btn.prev {
  left: -22px;
}

.carousel-btn.next {
  right: -22px;
}

/* ── TABS ── */
.tabs {
  display: flex;
  gap: 0.25rem;
  overflow-x: auto;
  scrollbar-width: none;
  padding: 0.25rem;
  background: var(--gray-100);
  border-radius: var(--radius-full);
  width: fit-content;
  max-width: 100%;
}

.tabs::-webkit-scrollbar {
  display: none;
}

.tab-btn {
  padding: 0.625rem 1.25rem;
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  color: var(--gray-500);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.tab-btn:hover {
  color: var(--gray-700);
}

.tab-btn.active {
  background: var(--white);
  color: var(--green);
  box-shadow: var(--shadow-sm);
}

.tab-panel {
  display: none;
  animation: fadeIn 300ms ease;
}

.tab-panel.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ── PLACEHOLDER IMAGES ── */
.img-placeholder {
  background: linear-gradient(135deg, var(--cream-light) 0%, var(--gray-100) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400);
  font-size: 0.75rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* ── RESPONSIVE ── */
@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }
  .split {
    grid-template-columns: 1fr;
    min-height: auto;
  }
  .split-content {
    padding: 2rem;
  }
  .split.reverse .split-img {
    order: 0;
  }
  .split.reverse .split-content {
    order: 0;
  }
}

@media (max-width: 768px) {
  .nav-links,
  .header-actions {
    display: none;
  }
  .mobile-menu-btn {
    display: flex;
  }
  .section {
    padding: 3rem 0;
  }
  .split-content h2 {
    font-size: 1.5rem;
  }
  .footer-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .footer-col {
    border-bottom: 1px solid rgba(255,255,255,0.1);
  }
  .footer-col h4 {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 0;
    margin-bottom: 0;
    cursor: pointer;
  }
  .footer-col .accordion-icon {
    display: block;
    transition: transform var(--transition-fast);
  }
  .footer-col.open .accordion-icon {
    transform: rotate(180deg);
  }
  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--transition-base), padding var(--transition-base);
    padding-bottom: 0;
  }
  .footer-col.open ul {
    max-height: 500px;
    padding-bottom: 1rem;
  }
  .carousel-btn.prev { left: 4px; }
  .carousel-btn.next { right: 4px; }
  .cookie-banner {
    flex-direction: column;
    text-align: center;
  }
  .tabs {
    width: 100%;
    justify-content: flex-start;
  }
}

