/* ── COOKIE BANNER ── */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 200;
  background: var(--white);
  box-shadow: 0 -4px 20px rgba(0,0,0,0.12);
  padding: 1.25rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.5rem;
  flex-wrap: wrap;
  transition: transform var(--transition-slow);
}

.cookie-banner.hidden {
  transform: translateY(100%);
  pointer-events: none;
}

.cookie-banner p {
  font-size: 0.875rem;
  color: var(--gray-600);
  max-width: 600px;
}

.cookie-banner strong {
  color: var(--gray-800);
  display: block;
  margin-bottom: 0.25rem;
}

.cookie-actions {
  display: flex;
  gap: 0.75rem;
  flex-shrink: 0;
}

/* ── SECTION UTILITIES ── */
.section {
  padding: 5rem 0;
}

.section-sm {
  padding: 3rem 0;
}

.section-alt {
  background: var(--off-white);
