.section-green {
  background: var(--green-light);
}

.text-center {
  text-align: center;
}

.text-green {
  color: var(--green);
}

.text-muted {
  color: var(--gray-500);
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.25rem 0.75rem;
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  text-transform: uppercase;
  letter-spacing: 0.03em;
