      document.getElementById('filterPanel').classList.toggle('visible');
      document.getElementById('filterToggle').classList.toggle('active');
    }

    function selectStore(card, num) {
      document.querySelectorAll('.store-card').forEach(c => c.classList.remove('active'));
      document.querySelectorAll('.map-pin').forEach(p => p.classList.remove('active'));
      card.classList.add('active');
      const pin = document.getElementById('pin-' + num);
      if (pin) pin.classList.add('active');
    }

    function selectPin(num) {
      document.querySelectorAll('.store-card').forEach(c => c.classList.remove('active'));
      document.querySelectorAll('.map-pin').forEach(p => p.classList.remove('active'));
      document.getElementById('pin-' + num).classList.add('active');
      const cards = document.querySelectorAll('.store-card');
      if (cards[num - 1]) {
        cards[num - 1].classList.add('active');
        cards[num - 1].scrollIntoView({ behavior: 'smooth', block: 'nearest' });
